import{_ as e,o as r,c as t,a3 as o}from"./chunks/framework.CZBGEXos.js";const m=JSON.parse('{"title":"Rol: Supervisor","description":"","frontmatter":{},"headers":[],"relativePath":"roles/supervisor.md","filePath":"roles/supervisor.md"}'),i={name:"roles/supervisor.md"};function d(s,a,l,n,c,p){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="rol-supervisor" tabindex="-1">Rol: Supervisor <a class="header-anchor" href="#rol-supervisor" aria-label="Permalink to &quot;Rol: Supervisor&quot;">​</a></h1><p>El <strong>supervisor</strong> lidera a un equipo de trabajadores en terreno. Es un rol operativo clave en la captura de firmas y el registro de actividades.</p><h2 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h2><ul><li>Supervisar a los trabajadores de su equipo en la obra.</li><li>Dictar y firmar charlas y capacitaciones como <strong>relator</strong>.</li><li><strong>Completar las actividades planificadas</strong> que le asigna la planificación mensual (rellenar el tema y detalle de cada día).</li><li><strong>Crear sus propias actividades</strong> cuando trabaja solo o tiene tareas adicionales no contempladas en la planificación.</li><li>Verificar y firmar la entrega de EPP.</li><li>Reportar incidentes y condiciones subestándar.</li></ul><h2 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Módulo</th><th>Acceso</th></tr></thead><tbody><tr><td>Dashboard</td><td>✓ Estado de su equipo y firmas pendientes</td></tr><tr><td>Obras</td><td>👁 Solo lectura</td></tr><tr><td>Documentos</td><td>👁 Solo lectura</td></tr><tr><td>Firmas</td><td>✓ Firma propia y como relator</td></tr><tr><td>Incidentes</td><td>✓ Reportar y dar seguimiento</td></tr><tr><td>Actividades</td><td>✓ Crear, completar borradores planificados y firmar como relator</td></tr><tr><td>Encuestas</td><td>👁 Solo lectura</td></tr><tr><td>Asistente IA</td><td>✗ Sin acceso</td></tr><tr><td>Personas</td><td>👁 Solo lectura (su equipo)</td></tr><tr><td>Bandeja de Entrada</td><td>✓ Completo</td></tr><tr><td>Tenants</td><td>✗ Sin acceso</td></tr></tbody></table><h2 id="actividades-planificadas" tabindex="-1">Actividades planificadas <a class="header-anchor" href="#actividades-planificadas" aria-label="Permalink to &quot;Actividades planificadas&quot;">​</a></h2><p>Cuando el prevencionista arma la <a href="/manual/modulos/actividades.html#planificar-el-mes-completo">planificación mensual</a>, el supervisor recibe <strong>borradores</strong> de sus actividades (charla diaria, inspecciones, etc.), uno por día hábil. Su tarea es <strong>completarlos</strong>: abrir el borrador (desde el calendario o la sección <em>&quot;Planificadas por completar&quot;</em>), rellenar el tema y detalle del día, y guardarlo para que quede programado y se convoque a los asistentes.</p><h2 id="firma-como-relator" tabindex="-1">Firma como relator <a class="header-anchor" href="#firma-como-relator" aria-label="Permalink to &quot;Firma como relator&quot;">​</a></h2><p>El supervisor es uno de los roles que puede actuar como <strong>relator</strong> en actividades (<code>CAPACITACION_SST</code>, <code>CHARLA_5MIN</code>). Su firma cruzada (<code>tipoFirma: relator</code>) certifica que la actividad se impartió, complementando las firmas de asistencia de los trabajadores. Ver <a href="/manual/ds44/capacitaciones.html">Capacitaciones</a> y <a href="/manual/modulos/firmas.html">Firmas</a>.</p><h2 id="verificacion-de-epp" tabindex="-1">Verificación de EPP <a class="header-anchor" href="#verificacion-de-epp" aria-label="Permalink to &quot;Verificación de EPP&quot;">​</a></h2><p>Firma como <code>supervisor</code> la entrega de EPP, validando que el trabajador recibió el equipo adecuado a su cargo. Ver <a href="/manual/ds44/epp.html">Entrega de EPP</a>.</p>',12)])])}const h=e(i,[["render",d]]);export{m as __pageData,h as default};
